const std = @import("std");

const Allocator = std.mem.Allocator;

pub const Options = struct {
    all: bool = false,
    dirs_only: bool = false,
    maxdepth: ?u64 = null,
    root: []const u8 = ".",
    rows: bool = false,
};

/// Errors the parser can fail with.  (No MissingOperand in v1: every
/// positional is optional-or-many via its dflt default; required
/// operands land with the mutator batch.)
pub const ParseError = error{
    UnknownOption,
    MissingValue,
    BadValue,
    Conflict,
    UnexpectedOperand,
    OutOfMemory,
};

/// Parse POSIX-style argv into Options.  args[0] is the program name
/// (skipped); `--` ends flag parsing; every matched flag sets its
/// field, coerced inline (the Dhall type never sees argv strings).
/// Accepted spellings: exact short/long tokens, argumentless short
/// clusters (-la == -l -a; a Value short never clusters) and inline
/// --long=value for Value longs.  Text operands are gpa-owned
/// dupes on success; on error earlier dupes are not freed (same
/// discipline as the hand parsers this replaces).
pub fn parsePosix(args: []const []const u8, gpa: Allocator) ParseError!Options {
    var next_pos: usize = 0; // next single-positional slot to fill
    var o = Options{};
    var i: usize = 1;
    var after_ddash = false;
    while (i < args.len) : (i += 1) {
        const a = args[i];
        if (after_ddash) {
            try bindOperand(a, &o, &next_pos, gpa);
            continue;
        }
        if (std.mem.eql(u8, a, "--")) {
            after_ddash = true;
            continue;
        }
        var matched = false;
        if (a.len > 2 and a[0] == '-' and a[1] != '-') {
            var cluster = true;
            for (a[1..]) |ch| {
                var letter_matched = false;
                if (ch == 'a') {
                    o.all = true;
                    letter_matched = true;
                }
                if (ch == 'd') {
                    o.dirs_only = true;
                    letter_matched = true;
                }
                if (!letter_matched) cluster = false;
            }
            if (cluster) continue;
        }
        if (!matched and (std.mem.eql(u8, a, "-a") or std.mem.eql(u8, a, "--all"))) {
            o.all = true;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-d") or std.mem.eql(u8, a, "--dirs-only"))) {
            o.dirs_only = true;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-L"))) {
            if (i + 1 >= args.len) {
                std.debug.print("fx-tree: option '-L' requires a value\n", .{});
                return error.MissingValue;
            }
            i += 1;
            o.maxdepth = std.fmt.parseInt(u64, args[i], 10) catch {
                std.debug.print("fx-tree: option '-L': '{s}' is not a Natural (u64)\n", .{ args[i] });
                return error.BadValue;
            };
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "--rows"))) {
            o.rows = true;
            matched = true;
        }
        if (!matched) {
            if (a.len > 1 and a[0] == '-') {
                std.debug.print("fx-tree: unknown option '{s}'\n", .{ a });
                return error.UnknownOption;
            }
            try bindOperand(a, &o, &next_pos, gpa);
        }
    }
    return o;
}

fn bindOperand(arg: []const u8, o: *Options, next_pos: *usize, gpa: Allocator) ParseError!void {
    if (next_pos.* == 0) {
        o.root = gpa.dupe(u8, arg) catch return error.OutOfMemory;
        next_pos.* = 1;
        return;
    }
    std.debug.print("fx-tree: unexpected operand '{s}'\n", .{ arg });
    return error.UnexpectedOperand;
}

pub fn usage() []const u8 {
    return "usage: fx-tree [OPTIONS] [ROOT]\n";
}

test "cli_tree: empty argv yields the dflt defaults" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const gpa = arena_state.allocator();
    const argv = [_][]const u8{ "fx-tree" };
    const o = try parsePosix(&argv, gpa);
    try std.testing.expectEqual(false, o.all);
    try std.testing.expectEqual(false, o.dirs_only);
    try std.testing.expectEqualStrings(".", o.root);
    try std.testing.expectEqual(false, o.rows);
}

